mapper.select:
SELECT FROM store_info s LEFT JOIN chain_franchise_account a ON a.store_id = s.id LEFT JOIN scm_customer c ON c.id = a.customer_id WHERE s.type = 'FRANCHISE'
AND (s.code LIKE CONCAT('%', #{keyword}, '%') OR s.name LIKE CONCAT('%', #{keyword}, '%') OR s.franchisee LIKE CONCAT('%', #{keyword}, '%'))
AND s.id = #{storeId} AND s.settle_mode = #{settleMode}
AND s.id IN #{sid}
ORDER BY s.sort, s.id
